const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  function getInfoAsync(obj) {
    return new Promise((resolve, reject) => obj.getInfo((d, e) => e ? reject(e) : resolve(d)));
  }

  try {
    // 1. Geometry & Time Definitions
    const gaul = ee.FeatureCollection('FAO/GAUL/2015/level1');
    const states = gaul.filter(ee.Filter.and(
      ee.Filter.eq('ADM0_NAME', 'India'),
      ee.Filter.inList('ADM1_NAME', ['Punjab', 'Haryana'])
    ));
    const region = states.geometry();

    async function monthStats(year) {
      const start = ee.Date.fromYMD(year, 11, 1);
      const end = start.advance(1, 'month');
      const col = ee.ImageCollection('NOAA/VIIRS/001/VNP14A1')
        .filterDate(start, end)
        .filterBounds(region);
      const n = await getInfoAsync(col.size());
      if (n === 0) {
        return {year, images: 0, empty: true};
      }
      const first = col.first().select('FireMask');
      const dataDict = first.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: region,
        scale: 1000,
        maxPixels: 1e9
      });
      const dataPix = await getInfoAsync(dataDict.get('FireMask')) ?? 0;

      const fireCol = col.map(img => img.select('FireMask').gt(6).rename('fire').selfMask());
      const sumImg = fireCol.sum();
      const uniqImg = fireCol.max();

      const sumDict = sumImg.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: region,
        scale: 1000,
        maxPixels: 1e9
      });
      const uniqDict = uniqImg.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: region,
        scale: 1000,
        maxPixels: 1e9
      });

      const fireSum = await getInfoAsync(sumDict.get('fire'));
      const fireUniq = await getInfoAsync(uniqDict.get('fire'));

      return {
        year,
        images: n,
        dataPix: (dataPix === null || dataPix === undefined) ? 0 : dataPix,
        fireSum: (fireSum === null || isNaN(fireSum)) ? 0 : fireSum,
        fireUniq: (fireUniq === null || isNaN(fireUniq)) ? 0 : fireUniq,
        empty: false
      };
    }

    const s2022 = await monthStats(2022);
    const s2024 = await monthStats(2024);

    // 2. Data Acquisition & Check
    if (s2022.empty || s2024.empty) {
      console.log('Collection check: 2022 imgs=' + s2022.images + ', 2024 imgs=' + s2024.images);
      console.log('Dataset: NOAA/VIIRS/001/VNP14A1 (FireMask>6 as fire)');
      console.log('C1');
      return;
    }

    if (s2022.dataPix === 0 || s2024.dataPix === 0) {
      console.log('Data pixels: 2022=' + s2022.dataPix + ', 2024=' + s2024.dataPix);
      console.log('C2');
      return;
    }

    // 3. Processing Stats (Concise Evidence)
    console.log('Dataset: NOAA/VIIRS/001/VNP14A1, Scale: 1000m');
    console.log('Nov 2022 Images: ' + s2022.images + ', DataPix: ' + s2022.dataPix);
    console.log('Nov 2022 FirePix(sum): ' + s2022.fireSum + ', FirePix(unique): ' + s2022.fireUniq);
    console.log('Nov 2024 Images: ' + s2024.images + ', DataPix: ' + s2024.dataPix);
    console.log('Nov 2024 FirePix(sum): ' + s2024.fireSum + ', FirePix(unique): ' + s2024.fireUniq);

    // 4. Validation & Final Answer
    function invalid(v) { return v === null || v === undefined || isNaN(v) || v < 0 || !isFinite(v); }
    if (invalid(s2022.fireUniq) || invalid(s2024.fireUniq)) {
      console.log('C3');
      return;
    }

    const answer = (s2024.fireUniq < s2022.fireUniq) ? 'A' : 'B';
    console.log(answer);
  } catch (err) {
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
